  @case 'the 5-limit column of the theory table'  [pure]  @ 434-439
  @case 'the score is the Tenney height of the sonority's octave-free lcm/gcd'  [pure]  @ 443-450
  @case 'the score is blind to where the sonority sits'  [pure]  @ 454-460
  @case 'a repeated member and an octave doubling cost nothing'  [pure]  @ 464-471
  @case 'springs: a spelled major triad, by hand'  [pure]  @ 475-484
