  @case 'a later strand of a class replaces the earlier one'  [pure]  @ 962-974
  @case 'a class still sounding stands where the last n struck have dropped it'  [pure]  @ 978-991
  @case 'the box is summed over the walk rather than over the onsets'  [pure]  @ 995-1000
  @case 'the pull is the strength times the square of a strand's strain'  [pure]  @ 1004-1009
