  @case 'at n one above the arity the resolution reads the seventh chord's bass alone'  [pure]  @ 1199-1217
  @case 'an exact tie goes to the first candidate rather than to table order'  [pure]  @ 1221-1241
  @case 'an empty shortlist and an unaffordable solve are both refused'  [pure]  @ 1245-1258

